/**
 * Sign-in with a passkey: the WEBAUTHN challenge of the authorize flow.
 *
 * <p>
 * The sign-in page asks the browser for an assertion ({@code webauthn.js}) and posts it here with
 * {@code step=webauthn-login}, the challenge id and the credential as JSON. A valid assertion, made
 * with user verification, identifies the user and proves two factors: the flow goes on as after a
 * password and an OTP (terms, consents, then the redirect with the code). Any failure shows the
 * login form again with an error.
 * </p>
 */
@Slf4j
@ApplicationScoped
@RequiredArgsConstructor
public class WebAuthnLoginStep implements OidcStep {

  /** Step name posted by the passkey sign-in form. */
  public static final String STEP = "webauthn-login";

  /** RFC 8176: key held in an authenticator, user verified on it, two factors. */
  private static final List<String> PASSKEY_AMR = List.of("hwk", "user", "mfa");

  private static final ObjectMapper JSON = new ObjectMapper();

  private final FinishAuthenticationUsecase finishAuthentication;
  private final WebAuthnRelyingParty relyingParty;
  private final LoginStep loginStep;

  @Override
  public AuthenticationChallenge challenge() {
    return AuthenticationChallenge.WEBAUTHN;
  }

  @Override
  public Set<String> stepNames() {
    return Set.of(STEP);
  }

  @Override
  public Response paint(StepInput input, NewCookie preSession) {
    throw new IllegalStateException("WebAuthnLoginStep is not triggered by a challenge exception");
  }

  @Override
  public Optional<StepOutcome> process(StepInput input) {
    if (!STEP.equals(input.step())) {
      return Optional.empty();
    }
    try {
      var rp = relyingParty.resolve(input.tenant());
      FinishAuthenticationResult result =
          finishAuthentication.finish(AuthorizeHtml.first(input.getFormParams(), "challengeId"),
              input.tenant(), credential(AuthorizeHtml.first(input.getFormParams(), "credential")),
              rp.origin(), rp.id());
      ChallengesState state = ChallengesState.empty(result.username())
          .withCompleted(AuthenticationChallenge.WEBAUTHN).withAmr(PASSKEY_AMR);
      return Optional.of(new StepOutcome.Proceed(result.username(), input.getClientDetails(),
          input.getRequest(), state));
    } catch (WebAuthnException | IllegalArgumentException | JsonProcessingException ex) {
      log.warn("Passkey sign-in rejected: {}", ex.getMessage());
      return Optional.of(new StepOutcome.Render(loginStep.paintForm(input.getRequest(), LoginStep
          .text(input.locale(), "login.passkey-failed", "The passkey could not be verified"))));
    }
  }

  private static Map<String, Object> credential(String json) throws JsonProcessingException {
    if (json == null || json.isBlank()) {
      throw WebAuthnException.credentialNotFound();
    }
    Map<String, Object> value = JSON.readValue(json, new TypeReference<Map<String, Object>>() {});
    return value == null ? Map.of() : value;
  }
}
